/**
 * pi-agent-panel — live in-session panel of running tasks (WS4).
 *
 * A pragmatic port of Claude Code's CoordinatorTaskPanel
 * (`src/components/CoordinatorAgentStatus.tsx`): an inline panel rendered below
 * the editor that lists running background agents with a status
 * icon, description, live elapsed time, and a running count. Terminal tasks
 * linger briefly then evict. `/agent-panel` opens an interactive control overlay
 * (↑/↓ select, Enter view output, x stop, Esc close).
 *
 * Fed by the unified task registry (WS2: `listTasks`/`subscribeTasks` spanning
 * background agents + local_bash). UI-only — no tool schema or system-prompt
 * change — so the prompt cache is untouched.
 *
 * Background shells (local_bash) stay out of the auto panel: they render as an
 * accent-colored "N shells" footer pill (Claude Code statusline parity). ↑/↓ on
 * an empty editor selects the pill, Enter expands/collapses the inline shell
 * rows under the agents section.
 */

import {
	findTaskAdapter,
	listTasks,
	subscribeTasks,
	type ExtensionAPI,
	type ExtensionCommandContext,
	type ExtensionContext,
} from "@valkyriweb/pi-coding-agent";
import { AgentPanelController, type PanelPainter } from "./panel.ts";
import { AgentPanelOverlay, type OverlayResult } from "./overlay.ts";
import { shellPillText } from "./format.ts";

const WIDGET_KEY = "agent-panel";

export default function agentPanelExtension(pi: ExtensionAPI): void {
	let controller: AgentPanelController | undefined;

	pi.on("session_start", (_event, ctx) => {
		controller?.dispose();
		controller = undefined;
		if (!ctx.hasUI) return;

		const painter = themePainter(ctx);
		controller = new AgentPanelController({
			listTasks,
			subscribeTasks,
			setWidget: (lines) =>
				ctx.ui.setWidget(WIDGET_KEY, lines, { placement: "belowEditor" }),
			painter,
		});
		controller.start();
	});

	// /new, /resume, fork, and quit all emit session_shutdown *before* the old
	// extension ctx is invalidated (agent-session-runtime.teardownCurrent), so
	// this is the safe place to stop painting. Waiting for the next
	// session_start instead leaves a window where the 1s tick or a task event
	// paints through the stale ctx and crashes pi with an uncaughtException.
	pi.on("session_shutdown", () => {
		controller?.dispose();
		controller = undefined;
	});

	// "N shells" footer pill — highlighted via accent, navigable with ↑/↓ on an
	// empty editor. Enter toggles the inline shell rows, but the footer stays terse.
	pi.registerFooter("agent-shells", {
		render: ({ theme, selected }) => {
			const label = shellPillText(listTasks());
			if (!label) return "";
			return theme.fg("accent", selected ? theme.bold(`▸ ${label}`) : label);
		},
		visible: () => shellPillText(listTasks()) !== "",
		onActivate: () => void controller?.toggleShells(),
	});

	pi.registerCommand("agent-panel", {
		description: "Open the live running-task panel (view output, stop tasks)",
		handler: async (_args, ctx) => openControlPanel(ctx),
	});
}

function themePainter(ctx: ExtensionContext): PanelPainter {
	const theme = ctx.ui.theme;
	return {
		header: (text) => theme.fg("accent", theme.bold(text)),
		row: (text, task) => {
			const color =
				task.status === "failed"
					? "error"
					: task.status === "completed"
						? "success"
						: task.status === "running"
							? "text"
							: "muted";
			return theme.fg(color, text);
		},
	};
}

async function openControlPanel(ctx: ExtensionCommandContext): Promise<void> {
	if (!ctx.hasUI) {
		ctx.ui.notify("agents panel requires interactive mode", "error");
		return;
	}

	const result = await ctx.ui.custom<OverlayResult>((tui, theme, _keybindings, done) => {
		return new AgentPanelOverlay(tui, theme, {
			snapshots: listTasks,
			stop: async (taskId) => {
				const adapter = findTaskAdapter(taskId);
				await (adapter?.kill?.(taskId) ?? adapter?.requestShutdown?.(taskId));
			},
			done,
		});
	});

	if (result.action === "view") {
		await viewTaskArtifact(ctx, result.taskId);
	}
}

async function viewTaskArtifact(ctx: ExtensionCommandContext, taskId: string): Promise<void> {
	const adapter = findTaskAdapter(taskId);
	const output = await adapter?.output?.(taskId, { mode: "tail", maxLines: 200 });
	if (!output) {
		ctx.ui.notify("No output available for that task.", "warning");
		return;
	}
	await ctx.ui.editor(`Task ${taskId}`, output.text);
}

