/**
 * AgentPanelController — drives the live inline panel below the editor.
 *
 * Subscribes to the unified task registry and re-sets a `belowEditor` widget
 * whenever tasks change, plus a 1s tick (only while rows are visible) so
 * elapsed time stays live. Agents auto-show as rows; `local_bash` shells stay
 * out of the auto rows (they live in the footer pill) and only render here when
 * the Shells section is expanded. Hides the widget when nothing is visible.
 * UI-only, so it is cache-neutral.
 *
 * Dependency-injected so the render/visibility/tick logic is unit-testable with
 * fakes — index.ts wires the real `listTasks`/`subscribeTasks`/`setWidget`/theme.
 */

import type { TaskSnapshot } from "@valkyriweb/pi-coding-agent";
import { headerText, isShell, rowText, shellHeaderText, visibleTasks } from "./format.ts";

/** Applies theme color to the plain lines. Identity by default (tests). */
export interface PanelPainter {
	header(text: string): string;
	row(text: string, task: TaskSnapshot): string;
}

const PLAIN_PAINTER: PanelPainter = { header: (t) => t, row: (t) => t };

export interface PanelDeps {
	listTasks: () => TaskSnapshot[];
	subscribeTasks: (cb: () => void) => () => void;
	/** Set the widget lines (undefined hides it). Caller owns key + placement. */
	setWidget: (lines: string[] | undefined) => void;
	painter?: PanelPainter;
	now?: () => number;
	/** Tick interval; injected in tests to avoid real timers. */
	setInterval?: (cb: () => void, ms: number) => unknown;
	clearInterval?: (handle: unknown) => void;
	tickMs?: number;
}

export class AgentPanelController {
	private unsubscribe?: () => void;
	private timer?: unknown;
	private disposed = false;
	/** Shells are collapsed into the footer pill by default; Enter on the pill expands. */
	private shellsExpanded = false;
	private readonly painter: PanelPainter;
	private readonly now: () => number;
	private readonly tickMs: number;
	private readonly setIntervalFn: (cb: () => void, ms: number) => unknown;
	private readonly clearIntervalFn: (handle: unknown) => void;

	constructor(private readonly deps: PanelDeps) {
		this.painter = deps.painter ?? PLAIN_PAINTER;
		this.now = deps.now ?? Date.now;
		this.tickMs = deps.tickMs ?? 1000;
		this.setIntervalFn = deps.setInterval ?? ((cb, ms) => setInterval(cb, ms));
		this.clearIntervalFn = deps.clearInterval ?? ((h) => clearInterval(h as ReturnType<typeof setInterval>));
	}

	start(): void {
		this.unsubscribe = this.deps.subscribeTasks(() => this.render());
		this.render();
	}

	/** Toggle the inline shells section (footer pill Enter). Returns the new state. */
	toggleShells(): boolean {
		this.shellsExpanded = !this.shellsExpanded;
		this.render();
		return this.shellsExpanded;
	}

	isShellsExpanded(): boolean {
		return this.shellsExpanded;
	}

	/** Recompute the widget and (re)arm the elapsed-time tick. */
	render(): void {
		if (this.disposed) return;
		const snapshots = this.deps.listTasks();
		const now = this.now();
		const agents = snapshots.filter((t) => !isShell(t));
		const shells = snapshots.filter(isShell);
		const visibleAgents = visibleTasks(agents, now);
		const visibleShells = this.shellsExpanded ? visibleTasks(shells, now) : [];

		const lines: string[] = [];
		if (visibleAgents.length > 0) {
			lines.push(this.painter.header(headerText(agents, now)));
			for (const task of visibleAgents) lines.push(this.painter.row(rowText(task, now), task));
		}
		if (visibleShells.length > 0) {
			lines.push(this.painter.header(shellHeaderText(shells, now)));
			for (const task of visibleShells) lines.push(this.painter.row(rowText(task, now), task));
		}

		if (lines.length === 0) {
			this.safeSetWidget(undefined);
			this.stopTimer();
			return;
		}

		this.safeSetWidget(lines);
		if (this.disposed) return; // paint hit a stale ctx → torn down, don't re-arm

		// We only reach here with ≥1 visible line (the empty case returned above), so
		// always keep ticking: running rows need live elapsed time, and terminal rows
		// need a final tick to evict after TERMINAL_RETAIN_MS.
		this.startTimer();
	}

	/**
	 * Paint through the host setWidget, tearing down silently if the host ctx
	 * has gone stale (session replaced before our session_shutdown handler ran,
	 * or an unforeseen replacement path). A failed paint must never take down
	 * pi — the next session_start builds a fresh controller on the new ctx.
	 */
	private safeSetWidget(lines: string[] | undefined): void {
		try {
			this.deps.setWidget(lines);
		} catch {
			this.teardown();
		}
	}

	/** Stop ticking + listening without touching the (possibly stale) widget. */
	private teardown(): void {
		this.disposed = true;
		this.stopTimer();
		this.unsubscribe?.();
		this.unsubscribe = undefined;
	}

	private startTimer(): void {
		if (this.timer !== undefined) return;
		this.timer = this.setIntervalFn(() => this.render(), this.tickMs);
	}

	private stopTimer(): void {
		if (this.timer === undefined) return;
		this.clearIntervalFn(this.timer);
		this.timer = undefined;
	}

	dispose(): void {
		this.teardown();
		this.safeSetWidget(undefined);
	}
}

