		["Agents · 1 running", "Shells · 1 running"],
		"expanded → both sections, agents first",
	);

	assert.equal(ctrl.toggleShells(), false, "toggle back collapses");
	assert.equal(widgetCalls.at(-1).some((l) => l.startsWith("Shells")), false, "collapsed → shells gone");
