// Regression: /new invalidated the old extension ctx before the panel stopped
// ticking; the next tick painted through the stale ctx and crashed pi with an
// uncaughtException ("This extension ctx is stale after session replacement").
{
	let stale = false;
	let widget;
	let cleared = 0;
	let unsubscribed = 0;
	const ctrl = new AgentPanelController({
		listTasks: () => [task()],
		subscribeTasks: () => () => (unsubscribed += 1),
		setWidget: (lines) => {
			if (stale) throw new Error("This extension ctx is stale after session replacement");
			widget = lines;
		},
		now: () => T0 + 3000,
		setInterval: () => "TIMER",
		clearInterval: () => (cleared += 1),
	});
	ctrl.start();
	assert.ok(Array.isArray(widget), "painted while ctx live");

	stale = true; // session replaced before our shutdown handler ran
	assert.doesNotThrow(() => ctrl.render(), "stale paint must not throw");
	assert.equal(cleared, 1, "timer cleared on stale paint");
	assert.equal(unsubscribed, 1, "registry unsubscribed on stale paint");
	assert.doesNotThrow(() => ctrl.dispose(), "dispose after stale ctx is safe");
}

